SELECT * FROM (SELECT p.id AS position_id, e.id AS event_id, e.observed_at, e.price, LAG(e.price) OVER w AS prev_price, TIMESTAMPDIFF(MICROSECOND, LAG(e.observed_at) OVER w, e.observed_at)/1000 AS gap_ms FROM crypto_ai.paper_position p JOIN crypto_ai.market_price_event e ON e.symbol=p.symbol AND e.observed_at BETWEEN p.opened_at AND p.closed_at WHERE p.id IN (172,182) WINDOW w AS (PARTITION BY p.id ORDER BY e.observed_at)) g WHERE gap_ms > 20000 ORDER BY position_id, observed_at LIMIT 40;
SELECT symbol, open_time, open_price, high_price, low_price, close_price, number_of_trades FROM crypto_ai.candle WHERE interval_code='1m' AND ((symbol='ACEUSDT' AND open_time BETWEEN '2026-10-12 09:56:00' AND '2026-10-12 10:06:00') OR (symbol='SHIBUSDT' AND open_time BETWEEN '2026-10-12 06:35:00' AND '2026-10-12 07:16:00')) ORDER BY symbol, open_time LIMIT 60;